import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"PhysisForcing: Physics Reinforced World Simulator for Robotic Manipulation","description":"","frontmatter":{"title":"PhysisForcing: Physics Reinforced World Simulator for Robotic Manipulation","arxiv":"2606.28128","date":"2026-06-26","authors":"Peiwen Zhang, Yufan Deng, Shangkun Sun, Juncheng Ma, Duomin Wang, Jonas Du, Zilin Pan, Ye Huang, Hao Liang, Songyan Huang, Ruihua Zhang, Enze Xie, Ming-Yu Liu, Daquan Zhou","categories":"cs.CV, cs.AI, cs.RO","topics":"物理感知视频生成, 世界模型, 表征对齐","outline":[2,2]},"headers":[],"relativePath":"papers/2606.28128.md","filePath":"papers/2606.28128.md","lastUpdated":null}'),l={name:"papers/2606.28128.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="physisforcing-physics-reinforced-world-simulator-for-robotic-manipulation" tabindex="-1">PhysisForcing: Physics Reinforced World Simulator for Robotic Manipulation <a class="header-anchor" href="#physisforcing-physics-reinforced-world-simulator-for-robotic-manipulation" aria-label="Permalink to &quot;PhysisForcing: Physics Reinforced World Simulator for Robotic Manipulation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2606.28128" target="_blank" rel="noreferrer">2606.28128</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-06-26</td></tr><tr><td><strong>作者</strong></td><td>Peiwen Zhang, Yufan Deng, Shangkun Sun, Juncheng Ma, Duomin Wang, Jonas Du, Zilin Pan, Ye Huang, Hao Liang, Songyan Huang, Ruihua Zhang, Enze Xie, Ming-Yu Liu, Daquan Zhou</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI, cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>只在&quot;物理信息区域&quot;上加两级表征对齐——用 CoTracker3 点轨迹监督 DiT 中间特征的逐点对应、用 V-JEPA 2 的 token 相似度矩阵监督其区域间关系，把物理约束做成训练期损失，推理零开销。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>把视频生成模型当具身世界模拟器，前提是生成的动力学不仅好看，而且物理上说得通。在接触密集的操作里，违反表现为两类：局部动力学错误（夹爪轨迹跳变、物体穿模、反重力运动），以及全局关系错误（被推的物体纹丝不动、被抓的物体飘走）。任何一类都让预测帧不再是&quot;该动作的合法后果&quot;，世界模型作为策略评测器或数据引擎的价值随之归零。</p><p>论文的定位是训练期的通用配方而非事后修补：不改推理流程、不加推理开销，只在微调阶段注入两级物理监督。收益体现在三个具身生成基准与两条下游具身指标上，其中最有说服力的一条是 WorldArena 动作规划协议下的闭环成功率从 16.0% 提到 24.0%。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>现有物理感知方法分三类。几何类通过深度预测、关键点跟踪或 3D 重建注入像素级一致性，RoboScape 联合学时序深度与关键点动力学，TesserAct、Ctrl-World 各有侧重。它们确实约束了局部空间结构，但不建模语义层面的交互结果——一个被推的物体只要自身形状稳定、跟踪连续，几何损失就满意，哪怕它根本没动。偏好类做后训练对齐，ABot-PhysWorld 用物理感知判别器做 DPO 抑制穿模与反重力，MIND-V 用 GRPO 配物理前瞻一致性奖励。它们的问题是&quot;事后纠正而非事前预防&quot;，且偏好信号稀疏、定位很弱——一条视频一个标量，无法告诉模型是哪一帧的哪个区域错了，代价往往是画质。仿真器类靠物理引擎或测试时筛选保证有效性，开销大且难扩展。</p><p>还有一条更基础的缺口：无论哪类方法，底层的重建目标都把接触区与背景像素一视同仁地加权。而物理证据在空间上是高度局部化的——集中在机械手、被操作物体、接触界面与运动部件上。均匀监督会稀释这些信号。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>作者先做诊断：通过大量实验把物理不稳定归到两个成因——运动物体的形变，以及交互实体之间不合理的时空相关性（尤其在接触时）。这两个成因天然对应两个不同的抽象层次，一个是逐点的，一个是逐区域对的。</p><p>于是问题变成：在这两个层次上分别去哪里拿监督信号？逐点层次有现成答案——离线点跟踪器给出稠密轨迹真值。逐区域对层次则需要一个&quot;关系测量空间&quot;，而自监督视频编码器的 token 相似度矩阵正好是这样一个空间：它不依赖任何标注，且其 token 已知带有物体与交互中心的结构。这条路在图像生成里已有 REPA 一系的先例（本文亦引用 VideoREPA），把它移到&quot;关系&quot;而非&quot;绝对特征&quot;上是自然的一步。</p><p>第三步是定位：既然物理证据集中在少数区域，就先把区域选出来。选法也不需要额外模型——点跟踪器已经跑了，位移和就是运动强度；再用首帧深度的倒数做前景加权，就能把背景抖动与远处无关运动压下去。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>物理合理性在操作视频里是分层的：局部要求每个点的轨迹连续、与接触相容；全局要求区域之间的关系随交互正确演化（夹爪与被抓物保持耦合、被推物随接触区一起移动）。这两件事分别可以用&quot;点跟踪器给的轨迹&quot;和&quot;自监督视频编码器给的 token 关系图&quot;来监督，而且都只需要施加在会发生交互的那一小片区域上——在背景上施加同样的损失只会稀释信号。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以一段&quot;把红苹果放到第二层木台&quot;的参考视频为例。</p><p><strong>区域提取。</strong> 在首帧铺 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">25</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">25</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">625</span></span></span></span> 个查询点，CoTracker3 离线模式给出稠密轨迹与可见性。每条轨迹的运动强度取位移和 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1539em;vertical-align:-0.2997em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1308em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∥</span><span class="mord"><span class="mord mathbf">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8542em;"><span style="top:-2.4231em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.1031em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2769em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0522em;vertical-align:-0.2587em;"></span><span class="mord"><span class="mord mathbf">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7936em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord">∥</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>；Depth-Anything-V2 给首帧相对深度，前景权重 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0728em;vertical-align:-0.2587em;"></span><span class="mord">1/</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathbf">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">ϵ</span><span class="mclose">)</span></span></span></span>，物理信息分 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>；以全体均值为自适应阈值二值化，再把选中的轨迹光栅化到每一帧，得到时空掩码 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathbf">M</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight" style="margin-right:0.0139em;">phy</span></span></span></span></span></span></span></span></span></span></span></span></span>。</p><p><strong>像素级对齐。</strong> 取 DiT 中间块的隐藏特征（A14B 上是第 20 块，宽 5120），经轻量 MLP 投影后重排成逐帧特征图。首帧特征当 query、其余帧当 key，对每个查询点算相似度图并在空间维 softmax，再用坐标期望得到预测点位 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0522em;vertical-align:-0.2587em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">p</span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7936em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span></span></span></span>，与 CoTracker3 的参考轨迹在掩码内做 MSE。</p><p><strong>语义级对齐。</strong> 同一块特征另经一个 MLP 投到 V-JEPA 2（ViT-L/16，vitl-fpc64-256）的特征空间并三线性重采样到其 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">32</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">16</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">16</span></span></span></span> 的时空 token 网格，使学生与教师 token 索引对齐。把掩码重采样到该分辨率，选出最多 512 个 token，在两侧各算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 的成对余弦关系矩阵，取逐元素 L1。</p><p>总损失 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">FM</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.3858em;vertical-align:-0.4188em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">pix</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.967em;"><span style="top:-2.4173em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">pix</span></span></span></span></span><span style="top:-3.1809em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight" style="margin-right:0.0139em;">phy</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4188em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0961em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal">λ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">sem</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">sem</span></span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight" style="margin-right:0.0139em;">phy</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span>。三个辅助模型全部冻结、只在训练时对真值片段实时运行，推理时全部丢弃。训练数据是 RoVid-X 的 4M 机器人片段经运动分、任务级去重与图文对齐过滤后剩下的约 500K 高质量片段。骨干覆盖 Wan2.2-I2V-A14B（只微调高噪专家并把它扩到全时间步）、Wan2.2-TI2V-5B（全参）、Cosmos3-Nano（LoRA，720p、最长 189 帧）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>两个损失的形式都简单，值得展开的是它们各自&quot;为什么能训得动&quot;。</p><p>像素级那一路本质是<strong>把 DiT 特征当描述子做可微匹配</strong>。式 (7) 的</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0906em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7079em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathbf">p</span></span><span style="top:-3.0134em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8436em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3717em;vertical-align:-1.3217em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8557em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathbf mtight">x</span><span class="mrel mtight">∈</span><span class="mord mtight">Ω</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3217em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Softmax</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1611em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathbf mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathbf">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8436em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathbf">x</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathbf">x</span></span></span></span></span></p><p>是一个 soft-argmax：直接取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">max</span></span></span></span> 不可导，取坐标的 softmax 期望则处处可导，梯度会同时推高真值位置的相似度、压低其他位置的相似度。因此这条损失并不要求 DiT 去&quot;画对&quot;，而是要求它的中间表示在时间上具有稳定的点级对应关系——这正是轨迹连续性在表示层的对应物。</p><p>语义级那一路的关键在于对齐的是<strong>关系矩阵而非绝对特征</strong>。式 (11) 只保留 token 两两之间的余弦角度，丢掉了范数、坐标系与维度语义。这意味着学生不需要与 V-JEPA 2 特征同构，只需要二者诱导的 token 图同构。正是这一点让一个完全冻结、训练目标毫不相关的自监督视频编码器可以充当&quot;语义测量空间&quot;：迁移的是结构而非内容。代价是这条损失对全局尺度与绝对位置完全不敏感——整个场景同比缩放或平移，关系矩阵不变。</p><p>掩码那一路的自适应阈值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8304em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≥</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2809em;vertical-align:-0.4358em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.162em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4358em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 也值得一提：用均值而非分位数意味着选中比例随分布形状变化。在长尾分布（少数点剧烈运动、多数静止）下选中比例远低于 50%，符合设计意图；但在整幅画面都在动的情况下，均值被整体抬高，选中比例反而回落到接近半幅画面，区域聚焦效果减弱。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>问题一：两级对齐能否提升具身视频生成？R-Bench（650 组图文对，五个任务维度 × 四个本体维度，用 Qwen3-VL 做 MLLM-as-Judge 打物理-语义合理性与任务遵循，另有两项基于跟踪统计的运动指标）上：Wan2.2-I2V-A14B 基座 50.7 → 普通微调 57.9 → PF-Wan 62.0（相对基座 +22.3%、相对普通微调 +7.1%，均为相对提升）；Cosmos3-Nano 58.4 → 61.5 → PF-Cosmos 63.8（+9.2% / +3.7%），后者是全表最高，超过最强商用模型 Wan2.6 的 60.7。PAI-Bench 机器人域：79.90 → 81.73、84.03 → 85.17。零样本的 EZS-Bench：79.04 → 80.54、80.29 → 81.08。</p><p>问题二：每个组件各贡献多少？表 4 在 TI2V-5B 上给出 44.8 → 只加像素 47.2 → 只加语义 46.2 → 全 47.5；在 A14B 上 57.9 → 62.0。表 5 显示不做区域聚焦（两个损失均匀施加）只到 46.0，做了到 47.5，Tasks 一维从 35.4 抬到 38.9。表 6 扫描对齐层，第 15 块最优（85.2），浅层 10 得 83.9、深层 25 得 83.2。</p><p>问题三：对具身决策有用吗？WorldArena 动作规划协议（世界模型配共享逆动力学模型，动作在 RoboTwin 2.0 里执行）平均闭环成功率 16.0% → 24.0%，高于最强基线 WoW 的 20.5%。把 PhysisForcing 训练的 TI2V-5B 换进 Fast-WAM 当视频骨干，六个 RoboTwin 2.0 任务（各 200 次 rollout）平均成功率 68.2% → 72.8%。</p><p>需要如实指出的问题有几处。表 4 里 TI2V-5B 的 Embodiments 一列，完整模型 58.2 <strong>低于</strong>只加像素损失的 59.0，总分靠 Tasks 拉回；表 5 的&quot;均匀施加两个损失&quot;46.0 也低于表 4 里&quot;只加像素损失（带区域聚焦）&quot;的 47.2，说明区域聚焦的重要性可能高于语义损失本身。下游策略六个任务里三个不升反降（shake_bottle −3.0、adjust_bottle 0.0、stack_bowls_two −6.5），平均 +4.6。R-Bench 的四足一列，A14B 基座 69.0 高于普通微调 65.6，PF 只回到 69.2；Cosmos 上四足从 73.1 降到 72.2。EZS-Bench 的 Quality 一列 PF-Cosmos 76.95 低于 Cosmos3-Nano(ft) 的 77.42 与 Kling 2.6 Pro 的 78.05；PAI-Bench 上 PF-Cosmos 的 Domain 93.26 只比 Abot-PhysWorld 的 93.06 高 0.20。交叉引用也有笔误：PAI-Bench 段落把图引作 Figure 4（实为 Figure 3），附录 C 写成&quot;Figure 4 and Figure 4&quot;。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p>五句话版：具身视频生成的物理违反可以归到局部轨迹错误与全局关系错误两层，而现有方法要么只管一层要么事后修补；PhysisForcing 把两层都做成训练期表征对齐——点跟踪器监督逐点对应、冻结自监督视频编码器的 token 关系矩阵监督区域耦合；两条损失只施加在由&quot;运动强度 × 前景深度权重&quot;选出的物理信息区域上，推理时零开销；三个基准与两条下游具身指标一致改善，闭环成功率 16.0% → 24.0%；但主基准与训练语料同源、且三套评测的物理信号都来自同族 VLM 判官，这限制了证据的独立性。</p><p>三句话版：把&quot;物理&quot;翻译成两个可直接监督的表示性质——点级时间对应与区域间关系结构。用两个冻结的现成模型提供真值，只在会发生交互的地方施加。收益在闭环成功率上兑现，在画质上略有代价。</p><p>一句话版：物理不是加一条损失去画对像素，而是把中间表示的对应关系和关系图对齐到会跟踪、会理解的模型上。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最承重的假设是：<strong>这三个基准上的分数提升等价于物理合理性的提升</strong>。R-Bench 的物理-语义合理性与任务遵循由 Qwen3-VL 打分，PAI-Bench 机器人域由 Qwen3-VL-235B-A22B 答 QA，EZS-Bench 由 Qwen3-VL-32B 出题、Qwen2.5-VL-72B 作答——三套评测的核心信号全部来自同族 VLM 判官。而 PhysisForcing 的语义级损失做的正是把一个自监督视频编码器的关系结构灌进 DiT。若 VLM 判官对&quot;区域关系协调&quot;的偏好与 V-JEPA 2 的表征偏好相关（二者都基于大规模视频自监督/弱监督），那么增益的一部分就是判官偏好的对齐，而非物理的改善。</p><p>同源性还有第二层。训练语料 RoVid-X 与主基准 R-Bench 出自同一篇工作（Deng 等，「Rethinking Video Generation Model for the Embodied World」，arXiv 2601.15282），而本文第二作者 Yufan Deng 与该引用的第一作者同姓——<strong>可以推断</strong>主基准与训练数据来自同一条流水线、同一批人。这不构成造假，但意味着 R-Bench 上的 +22.3% 不能当作独立验证。</p><p>论文确实提供了两条不依赖 VLM 打分的证据：WorldArena 闭环成功率与 Fast-WAM 下游策略成功率。这两条才是关键。但闭环只有两个任务、绝对值仅 22.0% 与 26.0%，下游策略六个任务里有三个变差。也就是说，真正独立的证据既稀薄又不一致。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做的最小验证是在 TI2V-5B 这个单卡可承受的档位上只复现像素级损失（它是单损失里增益更大的那条），用 500K 子集里切出的 20K 片段训 2k 步，然后同时测两件事。</p><p>第一件是复现方向：R-Bench 的 Tasks 维度是否重现 35.4 → 37.8 的方向。第二件是一个与训练目标形式相同但与评测判官完全无关的度量：把生成视频重新喂给 CoTracker3，计算被跟踪点相对参考轨迹的端点误差（EPE）。</p><p>判据很清晰。若 EPE 明显下降而 R-Bench 不动，说明损失确实改善了轨迹连续性，只是当前基准测不到，方法有效但评测需要换；若 R-Bench 上涨而 EPE 不动，说明涨的是判官偏好而不是物理量，§9 的担忧成立；两者同时改善才是干净的支持。这组实验不需要 A14B 的算力，也完全避开了 MLLM 判官。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最强的替代解释是：两条损失都属于&quot;在中间层挂一个辅助表征目标&quot;，其效果可能主要来自表征蒸馏与正则化本身，而不是&quot;物理&quot;这一特定内容。REPA 一系的经验表明，给扩散模型的中间层对齐一个强视觉编码器，即使目标与任务无关也能显著加速收敛并提升生成质量。</p><p>设计两组消融就能证伪或坐实：其一，把 CoTracker3 的参考轨迹<strong>随机置换</strong>（保持损失形式、掩码与梯度尺度不变，只破坏物理内容），看还剩多少增益；其二，把 V-JEPA 2 换成一个纯图像编码器（如 DINOv3，无任何时间建模），若关系对齐的增益基本保留，则&quot;视频编码器捕捉交互结构&quot;这一归因失效。只要随机标签版能保住一半以上的增益，论文的因果解释就必须改写。</p><p>另一条可预测的失败条件来自掩码本身。阈值取全体 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的均值，在<strong>相机自身运动</strong>的数据上（移动底盘、头部视角、第一人称本体）全图位移都很大，均值被整体抬高，掩码会退化到近似全图，区域聚焦失效——此时方法应当回落到表 5 的 46.0 档。论文所有实验都在相对固定的第三人称机器人视角上做，这个失败模式从未被测试，而它恰好覆盖了具身世界模型最重要的一类应用场景。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动 idea 的局限是：两条损失都需要<strong>真值视频</strong>才能计算（点轨迹与教师 token 都来自参考片段），因此它们只能用在有配对数据的监督微调里，无法用于纯动作条件的反事实 rollout——而后者才是世界模型的核心用途。这也解释了为什么闭环成功率的绝对值仍然只有 24%。</p><p>一个非增量的重新 framing 是：把语义级对齐从&quot;模仿一个冻结编码器在真值上的关系矩阵&quot;改成&quot;<strong>预测关系矩阵在给定动作下应当如何变化</strong>&quot;。也就是让 DiT 显式输出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span>，把世界模型的建模目标从像素演化换成关系图演化，像素解码退化成一个下游头。这样做有三个直接后果：监督信号变成动作条件的（可用于反事实）、接触事件变成关系图上可判定的离散事件（可直接算召回而不是靠 VLM 打分）、且关系图的维度远低于像素，可以在训练与评测里都跑得起长时程。</p><p>可借鉴的相邻领域工具是图神经网络的边预测与动态图预测，以及 JEPA 一系在隐空间做预测目标而非像素重建的经验。第一个实验很具体：在 RoboTwin 2.0 上，给同一初始帧配两组不同的动作 chunk（一组会产生接触、一组不会），用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 预测头判断哪一组产生接触，与仿真器给出的真实接触事件比 AUC。这个实验完全绕开生成质量与 VLM 判官，直接检验&quot;世界模型是否理解动作的物理后果&quot;。</p>',53)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
